  CrossmintWallets,
  WalletsApiClient,
  createCrossmint,
} = require("@crossmint/wallets-sdk");

const DEFAULT_MINT_BASE_URL = "https://www.crossmint.com/api/2022-06-09";
const DEFAULT_COLLECTION_ID = "default";

function requireEnv(name) {
  const value = process.env[name];
  if (!value) {
    throw new Error(`Missing environment variable: ${name}`);
  }
  return value;
}

function buildCrossmintClient() {
  const apiKey = requireEnv("CROSSMINT_API_KEY");
  const crossmint = createCrossmint({ apiKey });
  return {
    crossmint,
    walletsSdk: CrossmintWallets.from(crossmint),
    walletsApi: new WalletsApiClient(crossmint),
  };
}

async function createWalletAction(action) {
  const signerSecret = requireEnv("SIGNER_SECRET");
  const { walletsSdk } = buildCrossmintClient();

  const wallet = await walletsSdk.createWallet({
    chain: action.chain,
    owner: `userId:${action.userId}`,
    recovery: {
      type: "server",
      secret: signerSecret,
    },
  });

  return {
    success: true,
    address: wallet.address,
    chain: action.chain,
    userId: action.userId,
  };
}

async function checkBalanceAction(action) {
  const { walletsSdk } = buildCrossmintClient();
  const wallet = await walletsSdk.getWallet(action.walletAddress, {
    chain: action.chain,
  });
  const balances = await wallet.balances();
  const balance = balances?.nativeToken?.amount ?? "0";

  return {
    success: true,
    walletAddress: action.walletAddress,
    chain: action.chain,
    balance,
  };
}

