  const apiKey = requireEnv("CROSSMINT_API_KEY");
  const collectionId = process.env.CROSSMINT_COLLECTION_ID || DEFAULT_COLLECTION_ID;
  const baseUrl = process.env.CROSSMINT_MINT_BASE_URL || DEFAULT_MINT_BASE_URL;

